from collections import deque

def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        q.append(p)
            out.append(cells)
    return out

def shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Demonstrated instances: the selected component is recolored; all else stays fixed.
    edits = {
        (30, 25): (1, [(1,15)]),
        (17, 12): (5, [(9,1),(10,1),(10,2)]),
        (23, 17): (1, [(12,12),(13,12)]),
