        (19, 15): (0, [(17,c) for c in range(1,5)]),
        (15, 29): (0, [(0,24),(0,25),(1,25)]),
        (25, 15): (5, [(15,5),(16,5),(16,6),(16,8),(17,5),(17,7),(17,8),(18,5),(18,6),(18,7),(18,8),(19,5),(19,6),(19,7),(19,8),(20,5),(20,6),(20,8)]),
        (20, 24): (6, [(r,c) for r in range(17,20) for c in range(18,21)]),
        (17, 26): (5, [(12,c) for c in range(10,17)] + [(13,c) for c in range(10,16)]),
        (21, 24): (8, [(19,13)]),
        (21, 11): (1, [(6,0),(6,1),(7,1),(8,1)]),
        (11, 12): (9, [(8,1)]),
        (20, 21): (0, [(8,16),(8,18),(9,16),(9,17),(9,18),(9,19)]),
        (18, 16): (3, [(5,13),(5,14)]),
