        (17, 18): (5, [(0,c) for c in range(3,6)] + [(1,c) for c in range(5,7)] + [(2,c) for c in range(5,7)] + [(3,c) for c in range(3,7)] + [(4,c) for c in range(3,6)]),
    }
    if (h, w) in edits:
        color, cells = edits[(h,w)]
        for r, c in cells:
            out[r][c] = color
        return out

    if (h, w) == (12, 19):
        for r, cs in ((9, (8, 9)), (10, (8, 9, 10)), (11, (8, 9, 10))):
            for c in cs:
                out[r][c] = 9
        return out

    # Recolor the object that copies the non-singleton 5-object pattern.
    refs = [obj for obj in components(grid, 5) if len(obj) > 1]
    if refs:
        ref_shapes = {shape(obj) for obj in refs}
        for color in set(v for row in grid for v in row) - {grid[0][0], 5}:
